const timesheetPage = `-- name: TimesheetPage :many

SELECT t.id, t.user_id, t.class_id, t.class_session_id, t.teaching_date, t.scheduled_time, t.checkin_time, t.checkout_time, t.hours, t.late_minutes, t.early_leave_minutes, t.late_notified, t.hourly_rate, t.type, t.source, t.status, t.reviewed_by, t.reviewed_at, t.rejection_reason, t.adjusted_at, t.adjusted_by, t.adjustment_reason, t.notes, t.created_by, t.created_at, t.updated_at, u.full_name AS teacher_name, u.code::text AS teacher_code, COALESCE(c.code::text, '')::text AS class_code, COALESCE(c.name, '')::text AS class_name,
       s.shift_name, rv.full_name AS reviewer_name, ad.full_name AS adjuster_name, count(*) OVER () AS total
FROM hr.teacher_timesheets t
JOIN iam.users u ON u.id = t.user_id
LEFT JOIN academic.classes c ON c.id = t.class_id
LEFT JOIN academic.class_sessions s ON s.id = t.class_session_id
LEFT JOIN iam.users rv ON rv.id = t.reviewed_by
LEFT JOIN iam.users ad ON ad.id = t.adjusted_by
WHERE t.teaching_date BETWEEN $1 AND $2
  AND ($3::bool OR t.class_id = ANY($4::uuid[]))
  AND ($5::uuid IS NULL OR t.user_id = $5)
  AND ($6::uuid IS NULL OR c.branch_id = $6)
  AND ($7::uuid IS NULL OR t.class_id = $7)
  AND ($8::text IS NULL OR t.status = $8)
  AND ($9::text IS NULL OR t.type = $9)
  AND ($10::text IS NULL OR u.full_name ILIKE $10 OR u.code::text ILIKE $10)
ORDER BY t.teaching_date DESC, t.id DESC
LIMIT $12 OFFSET $11
`

